  async function saveService(event: React.FormEvent) {
    event.preventDefault();

    setSaving(true);
    setMessage("");

    try {
      const payload = {
        name: form.name,
        platform: form.platform,
        category: form.category,
        description: form.description,
        rate: form.rate,
        min: form.min,
        max: form.max,
        enabled: form.enabled,
        refill: form.refill,
        providerId: form.providerId,
        providerName: form.providerName,
      };

      const response = await fetch("/api/admin/services?debug=" + Date.now(), {
        method: editingId ? "PATCH" : "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(
          editingId
            ? {
                id: editingId,
                ...payload,
              }
            : payload
        ),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.error || "Unable to save service."
        );
      }

      setMessage(
        editingId
          ? `Service #${editingId} updated successfully.`
          : `Service #${data.service.id} created successfully.`
      );

      resetForm();
      await Promise.all([loadServices(), loadCategories()]);
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Unable to save service."
      );
    } finally {
      setSaving(false);
    }
  }

  async function toggleCategory(category: Category) {
    setMessage("");

    try {
      const response = await fetch("/api/admin/categories?fresh=" + Date.now(), {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          id: category.id,
          enabled: !category.enabled,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.error || "Unable to update category."
        );
      }

      setCategories((current) =>
        current.map((item) =>
          item.id === category.id
            ? { ...item, enabled: !category.enabled }
            : item
        )
      );

      setMessage(
        `${category.name} ${
          !category.enabled ? "enabled" : "disabled"
        } successfully.`
      );
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Unable to update category."
      );
    }
  }

  function normalizeCategoryName(value: string | null | undefined) {
  return (value || "")
    .normalize("NFKC")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
  }

  function toggleCategoryExpanded(categoryId: number) {
    setExpandedCategories((current) =>
      current.includes(categoryId)
        ? current.filter((id) => id !== categoryId)
        : [...current, categoryId]
    );
  }

  async function toggleService(service: Service) {
    setMessage("");

    try {
      const response = await fetch("/api/admin/services?debug=" + Date.now(), {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          id: service.id,
          enabled: !service.enabled,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.error || "Unable to update service."
        );
      }

      await loadServices();
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Unable to update service."
      );
    }
  }

  async function syncOrders() {
    setSyncing(true);
    setMessage("");

    try {
      const response = await fetch("/api/admin/orders/sync", {
        method: "POST",
        cache: "no-store",
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Unable to sync orders.");
      }

      setMessage(
        `Order sync complete. Checked ${data.checked}, updated ${data.updated}, failed ${data.failed}.`
      );
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Unable to sync orders."
      );
    } finally {
      setSyncing(false);
    }
  }

  async function deleteService(service: Service) {
    const confirmed = window.confirm(
      `Delete "${service.name}"? This only works if the service has no orders.`
    );

    if (!confirmed) return;

    try {
      const response = await fetch(
        `/api/admin/services?id=${service.id}`,
        {
          method: "DELETE",
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.error || "Unable to delete service."
        );
      }

      setMessage(`Service #${service.id} deleted.`);

      await loadServices();
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Unable to delete service."
      );
    }
  }
